writer.en:
values {
  flag = Flag {$on :runic:boolean}
  day = Day {$day :date}
  clock = At {$at :time}
  moment = At {$at :datetime}
  id = Id {$id :runic:uuid}
  big = Count {$n :integer}
  amount = Amount {$x :number}
}
steps {
  build = Building {$name}
  download =
    .input {$count :integer}
    .match $count
    one {{Downloading one file}}
    * {{Downloading {$count} files}}
  cleanup = Cleaning up
  check = Checking {$target}
}
operation {
  failed = {$step} failed
  summary = Changed {$names :runic:list}
  retry = Retry {$attempt} of {$total :integer}
  notice = Read the {#strong}notes{/strong}
}

